window.BABA = window.BABA || {};
window.BABA.Narration = {"questNames":{"text":"İsimlerin hükmünü sen verdin. Seçimin taşta kaldı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.39,"audio":""},"questVerdict":{"text":"Kanla yazılan hüküm değişti. Bedelini cellat ödeyecek.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.73,"audio":""},"questBell":{"text":"Çanın son sözü artık senin elinde.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":2.09,"audio":""},"questMemory":{"text":"Köklerin sakladığı hatıralara sen hükmettin.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":2.66,"audio":""},"questKing":{"text":"Kralın gizlediği ada sen hükmettin. Tahtın ilk bağı çözüldü.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.97,"audio":""},"questEcho":{"text":"Mağaranın soluğu değişti. Verdiğin hüküm burada kalacak.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.58,"audio":""},"questPrisoner":{"text":"Kuyudaki son yemin mühürlendi. Kararın geri alınamaz.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.46,"audio":""},"questHeart":{"text":"Ocağın beslemesi değişti. Son hüküm yaklaşıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.51,"audio":""},"ruinsIntro":{"text":"Taşın içinden gelen ses kralın değil, gömdüğü insanların sesi. Tahtın sakladığı adı bul; sana kalemi kimin verdiğini hatırla.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":9.585,"audio":"","chapter":3},"ruinsCheckpoint":{"text":"Son Yemin mühürlendi. Taht seni bekliyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.86,"audio":""},"ruinsBoss":{"text":"Oyukların Kralı. Tahtını yık.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":2.93,"audio":""},"ruinsWin":{"text":"Taht yıkıldı. Altındaki kapı açıldı. Zincirlerin dövüldüğü ocak orada.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.03,"audio":""},"forgeIntro":{"text":"Bu ocakta demirden önce insan yanar. Yazdığın adların ateşi hâlâ sönmedi; kalbi besleyen zincirleri kes.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.714,"audio":"","chapter":4},"forgeCheckpoint":{"text":"Köz Yemini mühürlendi. Son Döküm seni bekliyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.2,"audio":""},"forgeBoss":{"text":"Ocağın Kalbi. Son ateşi söndür.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.31,"audio":""},"forgeWin":{"text":"Ocak sustu. Mahkûmların besleme zinciri koptu. Kadı’nın arşivine giden yol açıldı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.245,"audio":"","chapter":4},"coastIntro":{"text":"Bu kıyıya borç ödendi diye yazmıştın. Çan her vuruşta ölüleri yeniden boğuyor; Selvi'nin izini onların son nefesinde ara.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":9.342,"audio":"","chapter":2},"coastRoots":{"text":"Yanmış ağaçların altında hâlâ kalpler atıyor. Her kök, toprağa gömülmüş birine uzanıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.452,"audio":""},"coastStreet":{"text":"Kapılar içeriden kilitlendi. Su yükselirken kimse birbirine yardım etmedi. Şimdi hepsi aynı sokakta bekliyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":10.116,"audio":""},"coastPier":{"text":"Fenerleri takip etme. O ışıklar tekneleri kıyıya değil, derinliğe çağırdı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.912,"audio":""},"coastSquare":{"text":"Meydanın altında yüzlerce mezar var. Çancı onların adlarını unuttu. Kökler unutmadı.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.496,"audio":""},"coastCheckpoint":{"text":"Yeminin bu fenerde kalacak. Çanlığa ilerle.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.94,"audio":""},"coastBoss":{"text":"Derinliklerin Çancısı. Çanı sustur.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.43,"audio":""},"coastDeath":{"text":"Deniz seni henüz almadı. Yemin seni kıyıya geri çağırıyor. Ayağa kalk.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.488,"audio":""},"coastDeath2":{"text":"Kökler bu kez tutamadı. Ama karanlık adını öğrendi. Yeniden yürü.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.344,"audio":""},"coastDeath3":{"text":"Çan hâlâ senin için çalıyor. Bu kıyıdan çıkmak istiyorsan onu sustur.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.264,"audio":""},"coastSeal":{"text":"Kökler gevşedi. Kıyının içlerine ilerle.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.356,"audio":""},"coastWin":{"text":"Çan sustu. Deniz çekiliyor. Yol, gömülü krallığa uzanıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.53,"audio":""},"intro":{"text":"Toprağın altında uyandın, Bahtiyar. Yazdığın isimler burada çürüyor; bu mezardan çıkmak için önce onların zincirlerini kırmalısın.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":10.122,"audio":"","chapter":1},"chains":{"text":"Bu nöbetçiler celladın ilk kurbanlarıydı. Boyunlarındaki zincir onları bugün bile celladın emrinde tutuyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.46,"audio":""},"ritual":{"text":"Yaralıları buraya iyileşsinler diye getirdiler. Rahipler onların acısıyla ayini besledi.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.236,"audio":""},"crypt":{"text":"Sunağa dökülen kan, cellada güç veriyor. Bu ayin bitmeden tapınak susmayacak.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":7.128,"audio":""},"rot":{"text":"Bu kemikler mezarlarından söküldü. Geçidin taşlarına harç oldular. Celladın zincirini ayakta tutuyorlar.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":9.792,"audio":""},"checkpoint":{"text":"Yemin taşı seni hatırlayacak. Yolun açık.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.77,"audio":""},"boss":{"text":"Cellat karşında. Zincirini kır.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":3.38,"audio":""},"heroOath":{"text":"Onları burada bırakmayacağım.","speaker":"Bahtiyar","voice":"tr-TR-AhmetNeural","style":"H","duration":2.088,"audio":""},"cellat":{"text":"Bu kapıdan kimse geçemez.","speaker":"Zincir Celladı","voice":"tr-TR-AhmetNeural","style":"E","duration":2.088,"audio":""},"seal":{"text":"Zincirin bir halkası daha koptu. İlerle.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.464,"audio":""},"death":{"text":"Yemin henüz bozulmadı. Taş seni geri çağırıyor.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.752,"audio":""},"death2":{"text":"Bu mezar seni tutamayacak. Ayağa kalk.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":4.32,"audio":""},"death3":{"text":"Bir kez daha düştün. Ama yemin bozulmadı. Zinciri kırmak için yeniden ayağa kalk.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":8.28,"audio":""},"win":{"text":"Cellat sustu. Zincir kırıldı. Açılan kapının ardında bir çan var.","speaker":"Anlatıcı","voice":"tr-TR-AhmetNeural","style":"D","duration":6.74,"audio":""}};
